installSql:
-- Supabase SQL Editor에서 실행. 앱에는 publishable/anon key만 사용합니다.
-- 테스트용 동일 회사 사용자 계정으로 데스크톱과 휴대폰에 로그인합니다.

create table if not exists public.demo_catalogs (
 owner_id uuid not null references auth.users(id),
 workspace_id uuid not null,
 revision text not null,
 payload jsonb not null,
 primary key(owner_id,workspace_id),
 constraint catalog_shape check (payload->>'format'='demo-catalog' and payload->>'version'='1' and payload->>'workspaceId'=workspace_id::text and jsonb_typeof(payload->'customers')='array' and jsonb_typeof(payload->'workRows')='array')
);
create table if not exists public.demo_events (
 owner_id uuid not null,
 workspace_id uuid not null,
 id uuid not null,
 kind text not null,
 happened_at timestamptz not null,
 payload jsonb not null check(jsonb_typeof(payload)='object' and octet_length(payload::text)<=16000),
 primary key(owner_id,workspace_id,id),
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
-- Re-running this script also upgrades projects created before direct sending.
alter table public.demo_events drop constraint if exists demo_events_kind_check;
alter table public.demo_events add constraint demo_events_kind_check check(kind in ('claim_created','composer_opened','dispatch_confirmed','payment_recorded','payment_voided','task_linked','dispatch_result','claim_deleted','completion_result','completion_confirmed'));

alter table public.demo_catalogs enable row level security;
alter table public.demo_events enable row level security;
revoke all on public.demo_catalogs,public.demo_events from anon,authenticated;
grant select,insert,update on public.demo_catalogs to authenticated;
grant select,insert on public.demo_events to authenticated;
drop policy if exists catalog_read on public.demo_catalogs;
create policy catalog_read on public.demo_catalogs for select to authenticated using(owner_id=(select auth.uid()));
drop policy if exists catalog_insert on public.demo_catalogs;
create policy catalog_insert on public.demo_catalogs for insert to authenticated with check(owner_id=(select auth.uid()));
drop policy if exists catalog_update on public.demo_catalogs;
create policy catalog_update on public.demo_catalogs for update to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
drop policy if exists event_read on public.demo_events;
create policy event_read on public.demo_events for select to authenticated using(owner_id=(select auth.uid()));
drop policy if exists event_insert on public.demo_events;
create policy event_insert on public.demo_events for insert to authenticated with check(owner_id=(select auth.uid()));
-- 이미지/로컬 경로/임의 필드는 동기화하지 않습니다. 이벤트는 추가만 가능합니다.
create or replace function public.demo_validate_event() returns trigger language plpgsql set search_path = '' as $$
declare allowed text[]; field text; value jsonb; p jsonb := new.payload; uuid_pattern text := '^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$';
begin
 allowed := case new.kind
 when 'claim_created' then array['customerId','graveId','taskKey','customerName','phone','address','amount','bank','account','accountHolder','body','photoCount','reportId']
 when 'payment_recorded' then array['claimId','amount','payer','note']
 when 'payment_voided' then array['claimId','paymentId']
 when 'dispatch_result' then array['claimId','attemptId','status']
 when 'completion_result' then array['claimId','attemptId','status']
 when 'task_linked' then array['taskKey','customerId','graveId']
 else array['claimId'] end;
 if (new.payload - allowed) <> '{}'::jsonb then raise exception 'Invalid event fields'; end if;
 if not isfinite(new.happened_at) then raise exception 'Invalid event time'; end if;
 for field,value in select * from jsonb_each(p) loop
  if jsonb_typeof(value)='string' and length(value #>> '{}')>4000 then raise exception 'Text too long'; end if;
 end loop;
 if new.kind in ('claim_created','payment_recorded') then
  if not coalesce(jsonb_typeof(p->'amount')='number' and (p->>'amount')::numeric>0 and (p->>'amount')::numeric<=1000000000000 and mod((p->>'amount')::numeric,1)=0,false) then raise exception 'Invalid amount'; end if;
 end if;
 if new.kind in ('claim_created','task_linked') then
  if not coalesce(jsonb_typeof(p->'customerId')='number' and mod((p->>'customerId')::numeric,1)=0 and abs((p->>'customerId')::numeric)<=9007199254740991,false) then raise exception 'Invalid customer'; end if;
  if not (new.kind='claim_created' and coalesce(p->'graveId'='null'::jsonb,false)) then
   if not coalesce(jsonb_typeof(p->'graveId')='number' and mod((p->>'graveId')::numeric,1)=0 and abs((p->>'graveId')::numeric)<=9007199254740991,false) then raise exception 'Invalid grave'; end if;
  end if;
  if p ? 'taskKey' and not coalesce(jsonb_typeof(p->'taskKey')='string' and length(p->>'taskKey')<=200,false) then raise exception 'Invalid task key'; end if;
 end if;
 if new.kind='claim_created' then
  if p ? 'reportId' and not coalesce(jsonb_typeof(p->'reportId')='string' and (p->>'reportId')~*'^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$',false) then raise exception 'Invalid report ID'; end if;
  foreach field in array array['customerName','address','bank','account','accountHolder','body'] loop
   if not coalesce(jsonb_typeof(p->field)='string' and length(btrim(p->>field))>0,false) then raise exception 'Missing claim field'; end if;
  end loop;
  if not coalesce(jsonb_typeof(p->'phone')='string' and p->>'phone' ~ '^0[0-9]{7,10}$',false) then raise exception 'Invalid phone'; end if;
  if not coalesce(jsonb_typeof(p->'photoCount')='number' and (p->>'photoCount')::numeric between 0 and 10 and mod((p->>'photoCount')::numeric,1)=0,false) then raise exception 'Invalid photo count'; end if;
 elsif new.kind='task_linked' then
  if not coalesce(jsonb_typeof(p->'taskKey')='string' and length(p->>'taskKey') between 1 and 200,false) then raise exception 'Missing task key'; end if;
 else
  if not coalesce(jsonb_typeof(p->'claimId')='string' and p->>'claimId' ~ uuid_pattern,false) then raise exception 'Invalid claim ID'; end if;
  if new.kind in ('dispatch_result','completion_result') and not coalesce(jsonb_typeof(p->'attemptId')='string' and p->>'attemptId' ~ uuid_pattern and p->>'status' in ('sent','failed','partial','unknown'),false) then raise exception 'Invalid delivery result'; end if;
  if new.kind='payment_recorded' then
   if not coalesce(jsonb_typeof(p->'payer')='string' and jsonb_typeof(p->'note')='string',false) then raise exception 'Invalid payment text'; end if;
  elsif new.kind='payment_voided' then
   if not coalesce(jsonb_typeof(p->'paymentId')='string' and p->>'paymentId' ~ uuid_pattern,false) then raise exception 'Invalid payment ID'; end if;
  end if;
 end if;
 return new;
end $$;

drop trigger if exists validate_event on public.demo_events;
create trigger validate_event before insert on public.demo_events for each row execute function public.demo_validate_event();

-- 동기화 순번은 작업공간별 행 잠금으로 발급합니다. 단순 sequence/시간은
-- 먼저 발급된 번호의 늦은 commit을 건너뛸 수 있으므로 사용하지 않습니다.
create table if not exists public.demo_sync_state (
 owner_id uuid not null,
 workspace_id uuid not null,
 generation uuid not null default gen_random_uuid(),
 head bigint not null default 0,
 primary key(owner_id,workspace_id),
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
create table if not exists public.demo_sync_changes (
 owner_id uuid not null,
 workspace_id uuid not null,
 seq bigint not null,
 kind text not null,
 key text not null,
 value jsonb,
 primary key(owner_id,workspace_id,seq),
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
create index if not exists demo_sync_events_index on public.demo_sync_changes(owner_id,workspace_id,seq) where kind='event';
alter table public.demo_sync_state enable row level security;
alter table public.demo_sync_changes enable row level security;
revoke all on public.demo_sync_state,public.demo_sync_changes from anon,authenticated;
grant select on public.demo_sync_state,public.demo_sync_changes to authenticated;
drop policy if exists sync_state_read on public.demo_sync_state;
create policy sync_state_read on public.demo_sync_state for select to authenticated using(owner_id=(select auth.uid()));
drop policy if exists sync_changes_read on public.demo_sync_changes;
create policy sync_changes_read on public.demo_sync_changes for select to authenticated using(owner_id=(select auth.uid()));

create or replace function public.demo_append_change(p_owner uuid,p_workspace uuid,p_kind text,p_key text,p_value jsonb)
returns void language plpgsql security definer set search_path='' as $$
declare next_seq bigint;
begin
 insert into public.demo_sync_state(owner_id,workspace_id) values(p_owner,p_workspace) on conflict do nothing;
 update public.demo_sync_state set head=head+1 where owner_id=p_owner and workspace_id=p_workspace returning head into next_seq;
 insert into public.demo_sync_changes values(p_owner,p_workspace,next_seq,p_kind,p_key,p_value);
end $$;
revoke all on function public.demo_append_change(uuid,uuid,text,text,jsonb) from public,anon,authenticated;

-- 고객 정렬 순서가 바뀌어도 전부 재전송하지 않도록 표시 순서는 ID 목록으로 보관합니다.
create or replace function public.demo_catalog_parts(p jsonb)
returns table(kind text,key text,value jsonb) language sql immutable set search_path='' as $$
 select 'customer',item->>'id',item from jsonb_array_elements(coalesce(p->'customers','[]')) item
 union all select 'grave',item->>'id',item from jsonb_array_elements(coalesce(p->'unassignedGraves','[]')) item
 union all select 'work',item->>'key',item from jsonb_array_elements(coalesce(p->'workRows','[]')) item
 union all select 'metadata','catalog',jsonb_build_object(
  'catalog',p - array['customers','unassignedGraves','workRows'],
  'order',jsonb_build_object(
   'customers',(select coalesce(jsonb_agg(item->>'id' order by pos),'[]') from jsonb_array_elements(coalesce(p->'customers','[]')) with ordinality t(item,pos)),
   'unassignedGraves',(select coalesce(jsonb_agg(item->>'id' order by pos),'[]') from jsonb_array_elements(coalesce(p->'unassignedGraves','[]')) with ordinality t(item,pos)),
   'workRows',(select coalesce(jsonb_agg(item->>'key' order by pos),'[]') from jsonb_array_elements(coalesce(p->'workRows','[]')) with ordinality t(item,pos))
  )) where p is not null;
$$;
revoke all on function public.demo_catalog_parts(jsonb) from public,anon,authenticated;
create or replace function public.demo_log_catalog(p_owner uuid,p_workspace uuid,previous jsonb,current_payload jsonb)
returns void language plpgsql security definer set search_path='' as $$
declare change record;
begin
 for change in
  select coalesce(n.kind,o.kind) as kind,coalesce(n.key,o.key) as key,n.value
  from public.demo_catalog_parts(previous) o full join public.demo_catalog_parts(current_payload) n using(kind,key)
  where o.value is distinct from n.value order by coalesce(n.kind,o.kind),coalesce(n.key,o.key)
 loop
  perform public.demo_append_change(p_owner,p_workspace,change.kind,change.key,change.value);
 end loop;
end $$;
revoke all on function public.demo_log_catalog(uuid,uuid,jsonb,jsonb) from public,anon,authenticated;
create or replace function public.demo_catalog_changed()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform public.demo_log_catalog(new.owner_id,new.workspace_id,case when TG_OP='UPDATE' then old.payload else null end,new.payload);
 return new;
end $$;
revoke all on function public.demo_catalog_changed() from public,anon,authenticated;
drop trigger if exists catalog_changed on public.demo_catalogs;
create trigger catalog_changed after insert or update on public.demo_catalogs for each row execute function public.demo_catalog_changed();
create or replace function public.demo_event_changed()
returns trigger language plpgsql security definer set search_path='' as $$
begin
 perform public.demo_append_change(new.owner_id,new.workspace_id,'event',new.id::text,
  jsonb_build_object('id',new.id,'workspaceId',new.workspace_id,'kind',new.kind,'at',new.happened_at,'payload',new.payload));
 return new;
end $$;
revoke all on function public.demo_event_changed() from public,anon,authenticated;
drop trigger if exists event_changed on public.demo_events;
create trigger event_changed after insert on public.demo_events for each row execute function public.demo_event_changed();

-- 기존 프로젝트도 같은 파일을 다시 실행하면 보유 자료부터 이어서 동기화합니다.
do $$ declare c record; e record;
begin
 for c in select * from public.demo_catalogs where not exists(select 1 from public.demo_sync_state s where s.owner_id=demo_catalogs.owner_id and s.workspace_id=demo_catalogs.workspace_id) loop
  perform public.demo_log_catalog(c.owner_id,c.workspace_id,null,c.payload);
 end loop;
 for e in select * from public.demo_events where not exists(select 1 from public.demo_sync_changes s where s.owner_id=demo_events.owner_id and s.workspace_id=demo_events.workspace_id and s.kind='event' and s.key=demo_events.id::text) loop
  perform public.demo_append_change(e.owner_id,e.workspace_id,'event',e.id::text,
   jsonb_build_object('id',e.id,'workspaceId',e.workspace_id,'kind',e.kind,'at',e.happened_at,'payload',e.payload));
 end loop;
end $$;

-- Status RPC is installed with access.sql after membership dependencies.

-- Run after database/cloud/schema.sql. Coordinates never enter catalog/event change history.

create table if not exists public.demo_map_snapshots (
 owner_id uuid not null, workspace_id uuid not null, payload jsonb not null,
 primary key(owner_id,workspace_id),
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id) on delete cascade
);
alter table public.demo_map_snapshots enable row level security;
revoke all on public.demo_map_snapshots from anon,authenticated;
grant select,insert,update on public.demo_map_snapshots to authenticated;
drop policy if exists map_owner on public.demo_map_snapshots;
create policy map_owner on public.demo_map_snapshots for all to authenticated using(owner_id=(select auth.uid())) with check(owner_id=(select auth.uid()));
create or replace function public.demo_validate_map_snapshot() returns trigger language plpgsql set search_path='' as $$
declare r jsonb; p jsonb; ids text[] := '{}'; kept jsonb := '[]'; now_ms numeric := extract(epoch from now())*1000;
begin
 if new.payload->>'workspaceId' is distinct from new.workspace_id::text or jsonb_typeof(new.payload->'locations') is distinct from 'array' or octet_length(new.payload::text)>20000000 or new.payload-array['workspaceId','locations'] <> '{}'::jsonb then raise exception 'Invalid map snapshot'; end if;
 for r in select * from jsonb_array_elements(new.payload->'locations') loop
  p := r->'location';
  if r-array['id','address','region','location'] <> '{}'::jsonb or jsonb_typeof(r->'id') is distinct from 'number' or (r->>'id')::numeric<>trunc((r->>'id')::numeric) or r->>'id'=any(ids) or jsonb_typeof(r->'address') is distinct from 'string' or jsonb_typeof(r->'region') is distinct from 'string' or jsonb_typeof(p) is distinct from 'object' then raise exception 'Invalid map row'; end if;
  ids := array_append(ids,r->>'id');
  if p-array['lat','lng','source','fetchedAt','expiresAt'] <> '{}'::jsonb or jsonb_typeof(p->'lat') is distinct from 'number' or jsonb_typeof(p->'lng') is distinct from 'number' or abs((p->>'lat')::numeric)>90 or abs((p->>'lng')::numeric)>180 or not coalesce(p->>'source' in ('field','public_parcel','google'),false) then raise exception 'Invalid coordinates'; end if;
  if p->>'source'='google' then
   if jsonb_typeof(p->'fetchedAt') is distinct from 'number' or jsonb_typeof(p->'expiresAt') is distinct from 'number' or (p->>'fetchedAt')::numeric>now_ms or (p->>'expiresAt')::numeric>(p->>'fetchedAt')::numeric+2592000000 then raise exception 'Invalid coordinate expiry'; end if;
   -- One day of headroom for scheduled cleanup; never extend the original lifetime.
   if (p->>'expiresAt')::numeric<=now_ms+86400000 then continue; end if;
  end if;
  kept := kept || jsonb_build_array(r);
 end loop;
 new.payload := jsonb_build_object('workspaceId',new.workspace_id,'locations',kept);
 return new;
end $$;
revoke all on function public.demo_validate_map_snapshot() from public,anon,authenticated;
drop trigger if exists validate_map_snapshot on public.demo_map_snapshots;
create trigger validate_map_snapshot before insert or update on public.demo_map_snapshots for each row execute function public.demo_validate_map_snapshot();
create or replace function public.demo_expire_map_snapshots() returns void language sql security definer set search_path='' as $$
 update public.demo_map_snapshots set payload=payload where exists (
 select 1 from jsonb_array_elements(payload->'locations') r where r->'location'->>'source'='google' and (r->'location'->>'expiresAt')::numeric<=extract(epoch from now())*1000+86400000);
$$;
revoke all on function public.demo_expire_map_snapshots() from public,anon,authenticated;

-- schema.sql, mobile-map.sql 적용 후 실행. 기존 회사 계정과 자료는 그대로 유지합니다.

create table if not exists public.demo_members (
 user_id uuid primary key references auth.users(id) on delete cascade,
 owner_id uuid not null,
 workspace_id uuid not null,
 login_id text not null check(login_id ~ '^[a-z0-9][a-z0-9._-]{2,31}$'),
 display_name text not null check(length(btrim(display_name)) between 1 and 80),
 role text not null check(role in ('worker','manager','master')),
 active boolean not null default true,
 created_at timestamptz not null default now(),
 unique(owner_id,workspace_id,login_id),
 check(user_id<>owner_id),
 foreign key(owner_id,workspace_id) references public.demo_catalogs(owner_id,workspace_id)
);
alter table public.demo_members drop constraint if exists demo_members_role_check;
alter table public.demo_members add constraint demo_members_role_check check(role in ('worker','manager','master'));
alter table public.demo_members enable row level security;
revoke all on public.demo_members from public,anon,authenticated;
grant select on public.demo_members to authenticated;
do $$ begin
 if exists(select from pg_roles where rolname='service_role') then
  grant select,insert,update,delete on public.demo_members to service_role;
 end if;
end $$;
-- 직원이 자신의 별도 카탈로그를 만들거나 기존 원본 API를 우회 사용하지 못하게 합니다.
create or replace function public.demo_is_staff() returns boolean
language sql stable security definer set search_path='' as $$
 select exists(select from public.demo_members where user_id=(select auth.uid()));
$$;
revoke all on function public.demo_is_staff() from public,anon;
grant execute on function public.demo_is_staff() to authenticated;
-- The company owner stays unchanged; master is an additional authorized actor.
create or replace function public.demo_can_manage(p_owner uuid,p_workspace uuid) returns boolean
language sql stable security definer set search_path='' as $$
 select (p_owner=auth.uid() and not public.demo_is_staff()) or exists(
  select from public.demo_members where user_id=auth.uid() and active and role='master'
  and owner_id=p_owner and workspace_id=p_workspace
 );
$$;
revoke all on function public.demo_can_manage(uuid,uuid) from public,anon;
grant execute on function public.demo_can_manage(uuid,uuid) to authenticated;
drop policy if exists member_read on public.demo_members;
create policy member_read on public.demo_members for select to authenticated
 using(user_id=auth.uid() or public.demo_can_manage(owner_id,workspace_id));
do $$ declare t text; begin
 foreach t in array array['demo_catalogs','demo_events','demo_sync_state','demo_sync_changes','demo_map_snapshots'] loop
  execute format('drop policy if exists staff_deny_raw on public.%I',t);
  execute format('create policy staff_deny_raw on public.%I as restrictive for all to authenticated using(public.demo_can_manage(owner_id,workspace_id)) with check(public.demo_can_manage(owner_id,workspace_id))',t);
  execute format('drop policy if exists company_managers on public.%I',t);
  execute format('create policy company_managers on public.%I for all to authenticated using(public.demo_can_manage(owner_id,workspace_id)) with check(public.demo_can_manage(owner_id,workspace_id))',t);
 end loop;
end $$;
-- Table GRANTs continue to prevent deleting catalog/events or writing sync history.
create or replace function public.demo_sync_status(p_workspace uuid)
returns jsonb language sql stable security invoker set search_path='' as $$
 select jsonb_build_object('workspaceId',s.workspace_id,'generation',s.generation,'head',s.head,'revision',c.revision)
 from public.demo_sync_state s join public.demo_catalogs c using(owner_id,workspace_id)
 where public.demo_can_manage(s.owner_id,s.workspace_id) and s.workspace_id=p_workspace;
$$;
revoke all on function public.demo_sync_status(uuid) from public,anon;
grant execute on function public.demo_sync_status(uuid) to authenticated;

create or replace function public.demo_access(p_workspace uuid) returns jsonb
language plpgsql stable security definer set search_path='' as $$
declare m public.demo_members; actor uuid := auth.uid();
begin
 if actor is null then raise exception 'Login required'; end if;
 select * into m from public.demo_members where user_id=actor;
 if found then
  if not m.active or m.workspace_id<>p_workspace then raise exception 'Account unavailable'; end if;
  return jsonb_build_object('role',m.role,'ownerId',m.owner_id,'workspaceId',m.workspace_id,'displayName',m.display_name);
 end if;
 if exists(select from public.demo_catalogs where owner_id=actor and workspace_id=p_workspace) then
  return jsonb_build_object('role','owner','ownerId',actor,'workspaceId',p_workspace,'displayName','사장님');
 end if;
 raise exception 'Company access not configured';
end $$;
revoke all on function public.demo_access(uuid) from public,anon;
grant execute on function public.demo_access(uuid) to authenticated;

create or replace function public.demo_earth_summary(p_earth jsonb,p_address text) returns jsonb
language plpgsql immutable set search_path='' as $$
declare result jsonb; confirmed text;
begin
 if jsonb_typeof(p_earth) is distinct from 'object'
  or p_earth->>'source' is distinct from 'google_earth_kml'
  or jsonb_typeof(p_earth->'originalAddress') is distinct from 'string'
  or p_earth->>'originalAddress' is distinct from p_address
  or jsonb_typeof(p_earth->'point'->'lat') is distinct from 'number'
  or jsonb_typeof(p_earth->'point'->'lng') is distinct from 'number'
  or (jsonb_typeof(p_earth->'areaM2') is distinct from 'null' and jsonb_typeof(p_earth->'areaM2') is distinct from 'number')
  or jsonb_typeof(p_earth->'confirmedAt') is distinct from 'string' then return null; end if;
 if abs((p_earth->'point'->>'lat')::numeric)>90 or abs((p_earth->'point'->>'lng')::numeric)>180 then return null; end if;
 if jsonb_typeof(p_earth->'areaM2')='number' and
   ((p_earth->>'areaM2')::numeric<0 or (p_earth->>'areaM2')::numeric>1.7976931348623157e308::numeric) then return null; end if;
 confirmed := p_earth->>'confirmedAt';
 if confirmed !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{3}Z$' then return null; end if;
 begin
  if not isfinite(confirmed::timestamptz) then return null; end if;
 exception when invalid_datetime_format or datetime_field_overflow then return null;
 end;
 result := jsonb_build_object('source','google_earth_kml','originalAddress',p_address,
  'point',jsonb_build_object('lat',p_earth->'point'->'lat','lng',p_earth->'point'->'lng'),
  'areaM2',p_earth->'areaM2','confirmedAt',confirmed);
 if jsonb_typeof(p_earth->'versionId')='string' and p_earth->>'versionId' ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
  result := result || jsonb_build_object('versionId',p_earth->'versionId');
 end if;
 if jsonb_typeof(p_earth->'sha256')='string' and p_earth->>'sha256' ~ '^[0-9a-f]{64}$' then
  result := result || jsonb_build_object('sha256',p_earth->'sha256');
 end if;
 return result;
end $$;
